-- ================================================================== -- DATABASE FIX - November 5, 2025 -- Fixes the ambiguous house_id error in create_house_with_owner -- ==================================================================
-- Fix the create_house_with_owner function -- Issue: "column reference 'house_id' is ambiguous" -- Solution: Add table alias 'hc' in the WHERE EXISTS clause -- ================================================================== CREATE OR REPLACE FUNCTION public.create_house_with_owner( p_name text, p_owner_id uuid, p_invite_code text, p_address text DEFAULT NULL, p_latitude double precision DEFAULT NULL, p_longitude double precision DEFAULT NULL ) RETURNS TABLE(house_id uuid, house_name text, invite_code text) LANGUAGE plpgsql SECURITY DEFINER AS $function$ DECLARE v_house_id uuid; BEGIN -- Insert house INSERT INTO houses (name, owner_id, invite_code, address, latitude, longitude) VALUES (p_name, p_owner_id, p_invite_code, p_address, p_latitude, p_longitude) RETURNING id INTO v_house_id;
-- Add owner as member (use ON CONFLICT to prevent duplicate key errors) INSERT INTO house_members (house_id, user_id, role) VALUES (v_house_id, p_owner_id, 'owner') ON CONFLICT (house_id, user_id) DO NOTHING;
-- Create default house config (only if not exists) -- Fixed: Added table alias 'hc' to resolve ambiguity INSERT INTO house_config (house_id, currency_code, currency_symbol) SELECT v_house_id, 'USD', '$' WHERE NOT EXISTS ( SELECT 1 FROM house_config hc WHERE hc.house_id = v_house_id );
-- Return house info -- Using explicit column aliases to avoid ambiguity with RETURNS TABLE columns RETURN QUERY SELECT v_house_id AS house_id, p_name AS house_name, p_invite_code AS invite_code; END; $function$;
-- Verification query to check if the function was updated SELECT proname as function_name, pg_get_functiondef(oid) as definition FROM pg_proc WHERE proname = 'create_house_with_owner' AND pronamespace = 'public'::regnamespace;

-- ================================================ -- FIX ALL FLOCKR ISSUES -- Run this entire SQL file in Supabase SQL Editor -- ================================================
-- 1. DROP THE DUPLICATE TRIGGERS (you have 2 triggers doing the same thing!) DROP TRIGGER IF EXISTS on_house_created ON houses; DROP TRIGGER IF EXISTS trigger_add_owner_as_member ON houses;
-- 2. FIX THE add_owner_as_member FUNCTION to handle duplicates CREATE OR REPLACE FUNCTION public.add_owner_as_member() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN -- Use ON CONFLICT to handle duplicates gracefully INSERT INTO house_members (house_id, user_id, joined_at) VALUES (NEW.id, NEW.owner_id, now()) ON CONFLICT (house_id, user_id) DO NOTHING;
RETURN NEW; END; $$;
-- 3. CREATE ONLY ONE TRIGGER (not two!) CREATE TRIGGER trigger_add_owner_as_member AFTER INSERT ON houses FOR EACH ROW EXECUTE FUNCTION add_owner_as_member();
-- 4. CLEAN UP any orphaned house_members (optional but recommended) DELETE FROM house_members WHERE house_id NOT IN (SELECT id FROM houses);
-- ================================================ -- VERIFICATION QUERIES (optional - run these to check) -- ================================================
-- Check triggers on houses table (should only see ONE add_owner trigger) -- SELECT trigger_name, event_manipulation, action_statement -- FROM information_schema.triggers -- WHERE event_object_table = 'houses' AND event_object_schema = 'public';
-- Check the function definition -- SELECT prosrc FROM pg_proc WHERE proname = 'add_owner_as_member';

-- COMPREHENSIVE FIX for Balance Bug -- Run this entire script in Supabase SQL Editor
-- Step 1: Clean up bad data (splits where user owes themselves) DELETE FROM public.expense_splits es USING public.one_time_expenses ote WHERE es.expense_id = ote.id AND es.user_id = ote.paid_by;
-- Step 2: Drop and recreate the RPC function with proper logic DROP FUNCTION IF EXISTS public.get_user_balances(uuid);
CREATE OR REPLACE FUNCTION public.get_user_balances(p_house_id uuid) RETURNS TABLE(user_id uuid, full_name text, balance numeric) LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN RETURN QUERY WITH expense_totals AS ( -- What each user has PAID SELECT ote.paid_by as user_id, SUM(ote.amount) as total_paid FROM one_time_expenses ote WHERE ote.house_id = p_house_id GROUP BY ote.paid_by ), expense_shares AS ( -- What each user OWES (excluding when they are the payer) SELECT es.user_id as user_id, SUM(es.amount_owed) as total_owed FROM expense_splits es JOIN one_time_expenses ote ON ote.id = es.expense_id WHERE ote.house_id = p_house_id AND es.user_id != ote.paid_by -- KEY FIX: Don't include splits where payer owes themselves GROUP BY es.user_id ), settlements AS ( SELECT t.payer_id as user_id, -SUM(t.amount) as settlement_balance FROM transactions t WHERE t.house_id = p_house_id AND t.is_settlement = true GROUP BY t.payer_id UNION ALL SELECT t.payee_id as user_id, SUM(t.amount) as settlement_balance FROM transactions t WHERE t.house_id = p_house_id AND t.is_settlement = true GROUP BY t.payee_id ), settlement_totals AS ( SELECT s.user_id, SUM(s.settlement_balance) as settlement_balance FROM settlements s GROUP BY s.user_id ), calculated_balances AS ( SELECT hm.user_id, p.full_name, -- Balance = what you paid - what you owe + settlements -- BUT: Only show balance if there are actual splits involving multiple people CASE WHEN EXISTS ( SELECT 1 FROM expense_splits es2 JOIN one_time_expenses ote2 ON es2.expense_id = ote2.id WHERE ote2.house_id = p_house_id AND (es2.user_id = hm.user_id OR ote2.paid_by = hm.user_id) ) THEN COALESCE(et.total_paid, 0) - COALESCE(es.total_owed, 0) + COALESCE(st.settlement_balance, 0) ELSE 0 -- No splits = no balance to show END as balance FROM house_members hm JOIN profiles p ON p.id = hm.user_id LEFT JOIN expense_totals et ON et.user_id = hm.user_id LEFT JOIN expense_shares es ON es.user_id = hm.user_id LEFT JOIN settlement_totals st ON st.user_id = hm.user_id WHERE hm.house_id = p_house_id ) SELECT cb.user_id, cb.full_name, cb.balance FROM calculated_balances cb WHERE ABS(cb.balance) >= 0.01 -- Only show non-zero balances ORDER BY cb.balance DESC; END; $$;
-- Step 3: Grant permissions GRANT EXECUTE ON FUNCTION public.get_user_balances(uuid) TO authenticated; GRANT EXECUTE ON FUNCTION public.get_user_balances(uuid) TO service_role;
-- Step 4: Add a database trigger to prevent bad splits from being created in future CREATE OR REPLACE FUNCTION public.prevent_self_owing_splits() RETURNS TRIGGER LANGUAGE plpgsql AS $$ DECLARE payer_id uuid; BEGIN -- Get the payer of this expense SELECT paid_by INTO payer_id FROM one_time_expenses WHERE id = NEW.expense_id;
-- If the split is for the payer themselves, don't insert it IF NEW.user_id = payer_id THEN RAISE NOTICE 'Prevented self-owing split: user % cannot owe themselves', NEW.user_id; RETURN NULL; -- Don't insert END IF;
RETURN NEW; END; $$;
-- Drop trigger if exists and create new one DROP TRIGGER IF EXISTS prevent_self_owing_splits_trigger ON public.expense_splits;
CREATE TRIGGER prevent_self_owing_splits_trigger BEFORE INSERT ON public.expense_splits FOR EACH ROW EXECUTE FUNCTION public.prevent_self_owing_splits();
-- Verification queries (run these to check if fix worked) -- Uncomment to run:
-- Check for any remaining bad splits (should return 0 rows) -- SELECT es.*, ote.paid_by -- FROM expense_splits es -- JOIN one_time_expenses ote ON ote.id = es.expense_id -- WHERE es.user_id = ote.paid_by;
-- Check balances for a specific house (replace with your house_id) -- SELECT * FROM get_user_balances('your-house-id-here');

-- Fix for get_user_balances RPC function -- This fixes the "you owe yourself" bug
DROP FUNCTION IF EXISTS public.get_user_balances(uuid);
CREATE OR REPLACE FUNCTION public.get_user_balances(p_house_id uuid) RETURNS TABLE(user_id uuid, full_name text, balance numeric) LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN RETURN QUERY WITH expense_totals AS ( -- What each user has PAID SELECT ote.paid_by as user_id, SUM(ote.amount) as total_paid FROM one_time_expenses ote WHERE ote.house_id = p_house_id GROUP BY ote.paid_by ), expense_shares AS ( -- What each user OWES (excluding when they are the payer) SELECT es.user_id as user_id, SUM(es.amount_owed) as total_owed FROM expense_splits es JOIN one_time_expenses ote ON ote.id = es.expense_id WHERE ote.house_id = p_house_id AND es.user_id != ote.paid_by -- KEY FIX: Don't include splits where payer owes themselves GROUP BY es.user_id ), settlements AS ( SELECT t.payer_id as user_id, -SUM(t.amount) as settlement_balance FROM transactions t WHERE t.house_id = p_house_id AND t.is_settlement = true GROUP BY t.payer_id UNION ALL SELECT t.payee_id as user_id, SUM(t.amount) as settlement_balance FROM transactions t WHERE t.house_id = p_house_id AND t.is_settlement = true GROUP BY t.payee_id ), settlement_totals AS ( SELECT s.user_id, SUM(s.settlement_balance) as settlement_balance FROM settlements s GROUP BY s.user_id ) SELECT hm.user_id, p.full_name, COALESCE(et.total_paid, 0) - COALESCE(es.total_owed, 0) + COALESCE(st.settlement_balance, 0) as balance FROM house_members hm JOIN profiles p ON p.id = hm.user_id LEFT JOIN expense_totals et ON et.user_id = hm.user_id LEFT JOIN expense_shares es ON es.user_id = hm.user_id LEFT JOIN settlement_totals st ON st.user_id = hm.user_id WHERE hm.house_id = p_house_id AND ( COALESCE(et.total_paid, 0) != COALESCE(es.total_owed, 0) OR COALESCE(st.settlement_balance, 0) != 0 ) -- Only show non-zero balances ORDER BY balance DESC; END; $$;
-- Grant necessary permissions GRANT EXECUTE ON FUNCTION public.get_user_balances(uuid) TO authenticated; GRANT EXECUTE ON FUNCTION public.get_user_balances(uuid) TO service_role;
-- EXPLANATION: -- The key fix is the line: AND es.user_id != ote.paid_by -- This ensures that when calculating what a user owes, we exclude splits -- where they are also the payer (which would be owing themselves). -- -- EXAMPLE: -- - You are alone in a house -- - You pay 676 for groceries -- - No splits are created (or if created, they are filtered out) -- - Result: total_paid = 676, total_owed = 0, balance = 676 - 0 = 676 -- - This shows correctly that you are owed 676 (from the house/others) -- -- EXAMPLE 2: -- - Three people: You, A, B -- - You pay 900 for dinner -- - Split equally: 300 each -- - Splits created: You owe 300, A owes 300, B owes 300 -- - With the fix: -- * You: paid 900, owe 0 (filtered out), balance = +600 (owed by others) -- * A: paid 0, owe 300, balance = -300 (owes you) -- * B: paid 0, owe 300, balance = -300 (owes you)

-- ============================================================================ -- NUCLEAR FIX - COMPLETELY DROP AND RECREATE FUNCTIONS -- Run this ENTIRE file in Supabase SQL Editor -- ============================================================================
-- ============================================================================ -- FIX 1: CREATE HOUSE WITH OWNER -- Drop the broken function completely and recreate from scratch -- ============================================================================
-- Drop the old broken function DROP FUNCTION IF EXISTS public.create_house_with_owner(text, uuid, text, text, double precision, double precision);
-- Create the fixed function with a completely different approach -- Using explicit output parameters instead of RETURNS TABLE CREATE OR REPLACE FUNCTION public.create_house_with_owner( p_name text, p_owner_id uuid, p_invite_code text, p_address text DEFAULT NULL, p_latitude double precision DEFAULT NULL, p_longitude double precision DEFAULT NULL, OUT out_house_id uuid, OUT out_house_name text, OUT out_invite_code text ) LANGUAGE plpgsql SECURITY DEFINER AS $function$ DECLARE v_new_house_id uuid; BEGIN -- Insert house INSERT INTO houses (name, owner_id, invite_code, address, latitude, longitude) VALUES (p_name, p_owner_id, p_invite_code, p_address, p_latitude, p_longitude) RETURNING id INTO v_new_house_id;
-- Add owner as member INSERT INTO house_members (house_id, user_id, role) VALUES (v_new_house_id, p_owner_id, 'owner') ON CONFLICT (house_id, user_id) DO NOTHING;
-- Create default house config INSERT INTO house_config (house_id, currency_code, currency_symbol) VALUES (v_new_house_id, 'USD', '$') ON CONFLICT (house_id) DO NOTHING;
-- Set output parameters (NO ambiguity possible!) out_house_id := v_new_house_id; out_house_name := p_name; out_invite_code := p_invite_code; END; $function$;
-- ============================================================================ -- FIX 2: GET PER DIEM BILL ITEMIZED -- Drop ALL overloaded versions and create ONE canonical version -- ============================================================================
-- Drop all versions of the function DROP FUNCTION IF EXISTS public.get_per_diem_bill_itemized(uuid, date); DROP FUNCTION IF EXISTS public.get_per_diem_bill_itemized(uuid, text);
-- Create single canonical version that accepts text and converts internally CREATE OR REPLACE FUNCTION public.get_per_diem_bill_itemized( p_house_id uuid, p_month text ) RETURNS TABLE( item_name text, category text, unit text, rate numeric, total_quantity numeric, total_amount numeric ) LANGUAGE plpgsql SECURITY DEFINER AS $function$ DECLARE v_month_date date; BEGIN -- Convert text to date (handles both 'yyyy-MM-dd' and 'yyyy-MM' formats) IF length(p_month) = 7 THEN v_month_date := (p_month || '-01')::date; ELSE v_month_date := p_month::date; END IF;
RETURN QUERY SELECT pdc.item_name, pdc.category, pdc.unit, pdc.rate, COALESCE(SUM(pde.quantity), 0) as total_quantity, COALESCE(SUM(pde.quantity * pdc.rate), 0) as total_amount FROM per_diem_config pdc LEFT JOIN per_diem_entries pde ON pde.config_id = pdc.id AND DATE_TRUNC('month', pde.date) = DATE_TRUNC('month', v_month_date) WHERE pdc.house_id = p_house_id AND pdc.is_active = true GROUP BY pdc.item_name, pdc.category, pdc.unit, pdc.rate HAVING COALESCE(SUM(pde.quantity), 0) > 0 ORDER BY total_amount DESC; END; $function$;
-- ============================================================================ -- FIX 3: GET PER DIEM BILL BY MEMBER (same overloading issue) -- ============================================================================
-- Drop all versions DROP FUNCTION IF EXISTS public.get_per_diem_bill_by_member(uuid, date); DROP FUNCTION IF EXISTS public.get_per_diem_bill_by_member(uuid, text);
-- Create single canonical version CREATE OR REPLACE FUNCTION public.get_per_diem_bill_by_member( p_house_id uuid, p_month text ) RETURNS TABLE( user_id uuid, full_name text, total_usage numeric, total_cost numeric ) LANGUAGE plpgsql SECURITY DEFINER AS $function$ DECLARE v_month_date date; BEGIN -- Convert text to date IF length(p_month) = 7 THEN v_month_date := (p_month || '-01')::date; ELSE v_month_date := p_month::date; END IF;
RETURN QUERY SELECT p.id as user_id, p.full_name, COALESCE(SUM(pde.quantity), 0) as total_usage, COALESCE(SUM(pde.quantity * pdc.rate), 0) as total_cost FROM profiles p JOIN house_members hm ON hm.user_id = p.id LEFT JOIN per_diem_entries pde ON pde.added_by = p.id AND DATE_TRUNC('month', pde.date) = DATE_TRUNC('month', v_month_date) LEFT JOIN per_diem_config pdc ON pdc.id = pde.config_id WHERE hm.house_id = p_house_id GROUP BY p.id, p.full_name HAVING COALESCE(SUM(pde.quantity), 0) > 0 ORDER BY total_cost DESC; END; $function$;
-- ============================================================================ -- VERIFICATION -- Run these to confirm functions are fixed -- ============================================================================
-- Check create_house_with_owner exists with OUT parameters SELECT proname as function_name, pg_get_function_arguments(oid) as arguments, pg_get_function_result(oid) as returns FROM pg_proc WHERE proname = 'create_house_with_owner' AND pronamespace = 'public'::regnamespace;
-- Check per diem functions - should only show text versions SELECT proname as function_name, pg_get_function_arguments(oid) as arguments FROM pg_proc WHERE proname IN ('get_per_diem_bill_itemized', 'get_per_diem_bill_by_member') AND pronamespace = 'public'::regnamespace ORDER BY proname;
-- Should return 3 rows total (1 for create_house, 2 for per_diem functions)

# Flockr UI Quick Reference Guide

## When Creating a New Screen

### 1. Standard Screen Template

```kotlin
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun YourScreen(
    onNavigateBack: () -> Unit,
    viewModel: YourViewModel = hiltViewModel()
) {
    Scaffold(
        topBar = {
            CenterAlignedTopAppBar(
                title = {
                    Text(
                        "Screen Title",
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.SemiBold
                    )
                },
                navigationIcon = {
                    IconButton(onClick = onNavigateBack) {
                        Icon(
                            Icons.AutoMirrored.Filled.ArrowBack,
                            "Back",
                            tint = MaterialTheme.colorScheme.onSurface
                        )
                    }
                },
                colors = TopAppBarDefaults.centerAlignedTopAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background
                )
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding),
            contentPadding = PaddingValues(24.dp),
            verticalArrangement = Arrangement.spacedBy(20.dp)
        ) {
            // Header
            item {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text(
                        text = "Main Heading",
                        style = MaterialTheme.typography.displaySmall,
                        fontWeight = FontWeight.Bold,
                        color = MaterialTheme.colorScheme.onBackground
                    )
                    Text(
                        text = "Description or subtitle",
                        style = MaterialTheme.typography.bodyLarge,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }

            // Your content here
        }
    }
}
```

### 2. Form Screen Template

```kotlin
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun YourFormScreen(
    onNavigateBack: () -> Unit,
    onSubmit: (Data) -> Unit,
    viewModel: YourViewModel = hiltViewModel()
) {
    var field1 by remember { mutableStateOf("") }
    var field2 by remember { mutableStateOf("") }
    val uiState by viewModel.uiState.collectAsState()

    Scaffold(
        topBar = { /* Same as above */ },
        containerColor = MaterialTheme.colorScheme.background
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 24.dp, vertical = 24.dp),
            verticalArrangement = Arrangement.spacedBy(20.dp)
        ) {
            // Header
            Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                Text(
                    text = "Form Title",
                    style = MaterialTheme.typography.displaySmall,
                    fontWeight = FontWeight.Bold
                )
                Text(
                    text = "Form description",
                    style = MaterialTheme.typography.bodyLarge,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }

            // Form Fields
            Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                FormField(
                    label = "Field 1 *",
                    value = field1,
                    onValueChange = { field1 = it },
                    placeholder = "Enter value",
                    icon = Icons.Default.YourIcon
                )

                FormField(
                    label = "Field 2",
                    value = field2,
                    onValueChange = { field2 = it },
                    placeholder = "Optional value"
                )
            }

            // Error Display
            if (uiState is YourUiState.Error) {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.errorContainer
                    ),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Text(
                        text = (uiState as YourUiState.Error).message,
                        color = MaterialTheme.colorScheme.onErrorContainer,
                        style = MaterialTheme.typography.bodyMedium,
                        modifier = Modifier.padding(16.dp)
                    )
                }
            }

            // Submit Button
            FlockrPrimaryButton(
                text = "Submit",
                onClick = { /* Submit logic */ },
                modifier = Modifier.fillMaxWidth(),
                enabled = field1.isNotBlank(),
                isLoading = uiState is YourUiState.Loading
            )
        }
    }
}
```

### 3. Form Field Component

```kotlin
@Composable
fun FormField(
    label: String,
    value: String,
    onValueChange: (String) -> Unit,
    modifier: Modifier = Modifier,
    placeholder: String = "",
    icon: ImageVector? = null,
    isError: Boolean = false,
    errorMessage: String? = null
) {
    Column(modifier = modifier) {
        Text(
            text = label,
            style = MaterialTheme.typography.labelLarge,
            color = MaterialTheme.colorScheme.onSurface,
            fontWeight = FontWeight.SemiBold,
            modifier = Modifier.padding(bottom = 8.dp)
        )
        FlockrTextField(
            value = value,
            onValueChange = onValueChange,
            placeholder = placeholder,
            leadingIcon = icon?.let { 
                {
                    Icon(
                        it, 
                        null,
                        tint = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            },
            modifier = Modifier.fillMaxWidth(),
            isError = isError
        )
        errorMessage?.let {
            Text(
                text = it,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.error,
                modifier = Modifier.padding(start = 16.dp, top = 4.dp)
            )
        }
    }
}
```

## Common Components Usage

### DataCard (for sections with content)

```kotlin
DataCard(
    title = "Section Title",
    subtitle = "Optional description"
) {
    // Your content here
    Text("Content inside card")
}
```

### CompactDataCard (for stats in rows)

```kotlin
Row(
    modifier = Modifier.fillMaxWidth(),
    horizontalArrangement = Arrangement.spacedBy(12.dp)
) {
    CompactDataCard(
        label = "This Month",
        value = "$1,234.56",
        modifier = Modifier.weight(1f),
        accentColor = MaterialTheme.colorScheme.primary
    )
    CompactDataCard(
        label = "Your Balance",
        value = "$567.89",
        modifier = Modifier.weight(1f),
        accentColor = MaterialTheme.colorScheme.secondary
    )
}
```

### ModernListItem (for navigation)

```kotlin
ModernListItem(
    title = "Feature Name",
    subtitle = "Brief description",
    icon = Icons.Default.Feature,
    onClick = { /* Navigate */ },
    showChevron = true
)
```

### FlockrTextField

```kotlin
FlockrTextField(
    value = value,
    onValueChange = { value = it },
    placeholder = "Hint text",
    label = "Optional Label",
    leadingIcon = {
        Icon(Icons.Default.Icon, null)
    },
    modifier = Modifier.fillMaxWidth(),
    isError = false,
    supportingText = "Optional help text"
)
```

### FlockrPrimaryButton

```kotlin
FlockrPrimaryButton(
    text = "Action Text",
    onClick = { /* Action */ },
    modifier = Modifier.fillMaxWidth(),
    enabled = true,
    isLoading = false
)
```

## Spacing Guidelines

- **Horizontal Screen Padding**: 24dp
- **Vertical Screen Padding**: 24dp
- **Item Spacing (LazyColumn)**: 20dp
- **Form Field Spacing**: 16dp
- **Section Spacing**: 24dp
- **Text Element Spacing**: 8dp

## Common Patterns

### Loading State

```kotlin
when (val state = uiState) {
    is UiState.Loading -> {
        Box(
            modifier = Modifier.fillMaxSize(),
            contentAlignment = Alignment.Center
        ) {
            CircularProgressIndicator()
        }
    }
    is UiState.Success -> {
        // Your content
    }
    is UiState.Error -> {
        // Error display
    }
}
```

### Empty State

```kotlin
Card(
    modifier = Modifier
        .fillMaxWidth()
        .padding(32.dp),
    colors = CardDefaults.cardColors(
        containerColor = MaterialTheme.colorScheme.surfaceVariant
    )
) {
    Column(
        modifier = Modifier.padding(32.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Icon(
            imageVector = Icons.Default.EmptyIcon,
            contentDescription = null,
            modifier = Modifier.size(72.dp),
            tint = MaterialTheme.colorScheme.primary
        )
        Text(
            text = "No items yet",
            style = MaterialTheme.typography.headlineSmall,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.padding(top = 16.dp)
        )
        Text(
            text = "Description of empty state",
            style = MaterialTheme.typography.bodyLarge,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            textAlign = TextAlign.Center,
            modifier = Modifier.padding(top = 8.dp)
        )
        FlockrPrimaryButton(
            text = "Add Item",
            onClick = { /* Action */ },
            modifier = Modifier
                .fillMaxWidth()
                .padding(top = 24.dp)
        )
    }
}
```

### FAB (Floating Action Button)

```kotlin
ExtendedFloatingActionButton(
    onClick = { /* Action */ },
    icon = { Icon(Icons.Default.Add, "Add") },
    text = { Text("Add Item") },
    containerColor = MaterialTheme.colorScheme.primary,
    shape = RoundedCornerShape(16.dp)
)
```

## Color Usage

```kotlin
// Background
containerColor = MaterialTheme.colorScheme.background

// Card surface
containerColor = MaterialTheme.colorScheme.surface

// Subtle background
containerColor = MaterialTheme.colorScheme.surfaceVariant

// Primary action
containerColor = MaterialTheme.colorScheme.primary

// Error state
containerColor = MaterialTheme.colorScheme.errorContainer
color = MaterialTheme.colorScheme.onErrorContainer

// Secondary text
color = MaterialTheme.colorScheme.onSurfaceVariant

// Border
color = MaterialTheme.colorScheme.outline.copy(alpha = 0.3f)
```

## Typography Usage

```kotlin
// Screen titles (in TopAppBar)
style = MaterialTheme.typography.titleLarge
fontWeight = FontWeight.SemiBold

// Section headers
style = MaterialTheme.typography.displaySmall
fontWeight = FontWeight.Bold

// Subsection headers
style = MaterialTheme.typography.titleMedium
fontWeight = FontWeight.Bold

// Body text
style = MaterialTheme.typography.bodyLarge

// Form labels
style = MaterialTheme.typography.labelLarge
fontWeight = FontWeight.SemiBold

// Secondary/descriptive text
style = MaterialTheme.typography.bodyLarge
color = MaterialTheme.colorScheme.onSurfaceVariant
```

## Don'ts

❌ Don't use TopAppBar - use CenterAlignedTopAppBar
❌ Don't use all caps titles (e.g., "SETTINGS") - use sentence case
❌ Don't forget to add descriptive subtitles under main headings
❌ Don't skip form field labels
❌ Don't use inconsistent spacing
❌ Don't forget to set containerColor on Scaffold
❌ Don't use high elevation (stick to 0-2dp)
❌ Don't forget navigation icon color (onSurface)

## Do's

✅ Use CenterAlignedTopAppBar for consistency
✅ Add descriptive subtitles under headings
✅ Label all form fields clearly
✅ Use 24dp horizontal padding for content
✅ Use DataCard and ModernListItem components
✅ Set containerColor = background on Scaffold
✅ Use subtle borders (1dp, 0.3 alpha)
✅ Add loading and error states
✅ Use FlockrPrimaryButton for primary actions
✅ Maintain consistent spacing (20-24dp)

## Animation Example

```kotlin
val interactionSource = remember { MutableInteractionSource() }
val isPressed by interactionSource.collectIsPressedAsState()

val scale by animateFloatAsState(
    targetValue = if (isPressed) 0.97f else 1f,
    animationSpec = spring(
        dampingRatio = Spring.DampingRatioMediumBouncy,
        stiffness = Spring.StiffnessMedium
    ),
    label = "scale_animation"
)

Surface(
    modifier = Modifier.scale(scale),
    // ... other properties
) {
    // Content
}
```

---

Keep this guide handy when developing new screens to maintain consistency!

package `in`.xroden.flockr.data.repository

import `in`.xroden.flockr.data.model.CreateNotificationParams
import `in`.xroden.flockr.data.model.GetPerDiemBillByMonthParams
import `in`.xroden.flockr.data.model.GetPerDiemBillParams
import `in`.xroden.flockr.data.model.GetPerDiemEntriesWithDetailsParams
import `in`.xroden.flockr.data.model.PerDiemConfig
import `in`.xroden.flockr.data.model.PerDiemConfigActivation
import `in`.xroden.flockr.data.model.PerDiemConfigInsert
import `in`.xroden.flockr.data.model.PerDiemConfigUpdate
import `in`.xroden.flockr.data.model.PerDiemEntry
import `in`.xroden.flockr.data.model.PerDiemEntryInsert
import `in`.xroden.flockr.data.model.PerDiemEntryWithDetails
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.gotrue.auth
import io.github.jan.supabase.postgrest.from
import io.github.jan.supabase.postgrest.postgrest
import io.github.jan.supabase.postgrest.query.Columns
import io.github.jan.supabase.postgrest.rpc
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class PerDiemRepository @Inject constructor(
    private val supabase: SupabaseClient
) {
    private val userId: String?
        get() = supabase.auth.currentUserOrNull()?.id

    suspend fun getPerDiemConfigs(houseId: String): List<PerDiemConfig> {
        return try {
            android.util.Log.d("PerDiemRepository", "Getting per-diem configs for house: $houseId")
            val configs = supabase.from("per_diem_config")
                .select(Columns.ALL) {
                    filter {
                        eq("house_id", houseId)
                        eq("is_active", true)
                    }
                }
                .decodeList<PerDiemConfig>()
            android.util.Log.d("PerDiemRepository", "Found ${configs.size} per-diem configs")
            configs
        } catch (e: Exception) {
            android.util.Log.e("PerDiemRepository", "Error getting per-diem configs", e)
            emptyList()
        }
    }

    suspend fun getPerDiemEntries(houseId: String, configId: String? = null): List<PerDiemEntry> {
        return try {
            supabase.from("per_diem_entries")
                .select(Columns.ALL) {
                    filter {
                        if (configId != null) {
                            eq("config_id", configId)
                        }
                    }
                    order("date", io.github.jan.supabase.postgrest.query.Order.DESCENDING)
                }
                .decodeList<PerDiemEntry>()
        } catch (e: Exception) {
            emptyList()
        }
    }

    suspend fun createPerDiemConfig(
        houseId: String,
        itemName: String,
        rate: Double,
        category: String,
        unit: String
    ): Result<PerDiemConfig> {
        return try {
            android.util.Log.d("PerDiemRepository", "Creating per-diem config: $itemName")
            val configInsert = PerDiemConfigInsert(
                houseId = houseId,
                itemName = itemName,
                rate = rate,
                category = category,
                unit = unit,
                isActive = true
            )
            val config = supabase.from("per_diem_config")
                .insert(configInsert) {
                    select()
                }
                .decodeSingle<PerDiemConfig>()

            android.util.Log.d("PerDiemRepository", "Per-diem config created with id: ${config.id}")
            Result.success(config)
        } catch (e: Exception) {
            android.util.Log.e("PerDiemRepository", "Error creating per-diem config", e)
            Result.failure(e)
        }
    }

    suspend fun updatePerDiemConfig(
        configId: String,
        itemName: String,
        rate: Double,
        category: String,
        unit: String
    ): Result<Unit> {
        return try {
            val update = PerDiemConfigUpdate(
                itemName = itemName,
                rate = rate,
                category = category,
                unit = unit
            )
            supabase.from("per_diem_config")
                .update(update) {
                    filter {
                        eq("id", configId)
                    }
                }

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun deletePerDiemConfig(configId: String, deleteUsage: Boolean = false): Result<Unit> {
        return try {
            if (deleteUsage) {
                // Delete all associated usage entries first
                supabase.from("per_diem_entries")
                    .delete {
                        filter {
                            eq("config_id", configId)
                        }
                    }
            }

            // Soft delete the config by setting isActive to false
            val activation = PerDiemConfigActivation(isActive = false)
            supabase.from("per_diem_config")
                .update(activation) {
                    filter {
                        eq("id", configId)
                    }
                }

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun addPerDiemEntry(
        houseId: String,
        configId: String,
        quantity: Double,
        date: String,
        itemName: String
    ): Result<PerDiemEntry> {
        return try {
            val currentUserId = userId ?: return Result.failure(Exception("No user logged in"))

            val entryInsert = PerDiemEntryInsert(
                configId = configId,
                quantity = quantity,
                date = date,
                addedBy = currentUserId,
                notes = null
            )
            val entry = supabase.from("per_diem_entries")
                .insert(entryInsert) {
                    select()
                }
                .decodeSingle<PerDiemEntry>()

            // Create notification for house members
            val notificationParams = CreateNotificationParams(
                houseId = houseId,
                title = "Per-Diem Entry Added",
                message = "$itemName entry added: $quantity units.",
                data = """{"id":"${entry.id}","type":"per_diem"}""",
                excludeUserId = currentUserId
            )
            supabase.postgrest.rpc(
                function = "create_notification_for_house",
                parameters = notificationParams
            ).decodeAs<Unit>()

            Result.success(entry)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun updatePerDiemEntry(
        entryId: String,
        quantity: Double,
        date: String,
        notes: String?
    ): Result<Unit> {
        return try {
            val update = mapOf(
                "quantity" to quantity,
                "date" to date,
                "notes" to notes
            )
            supabase.from("per_diem_entries")
                .update(update) {
                    filter {
                        eq("id", entryId)
                    }
                }

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun deletePerDiemEntry(entryId: String): Result<Unit> {
        return try {
            supabase.from("per_diem_entries")
                .delete {
                    filter {
                        eq("id", entryId)
                    }
                }

            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getPerDiemEntriesWithDetails(houseId: String, month: String? = null): List<PerDiemEntryWithDetails> {
        return try {
            val monthDate = if (month != null && month.length == 7) "$month-01" else month
            val params = GetPerDiemEntriesWithDetailsParams(houseId = houseId, month = monthDate)
            supabase.postgrest.rpc(
                function = "get_per_diem_entries_with_details",
                parameters = params
            ).decodeList<PerDiemEntryWithDetails>()
        } catch (e: Exception) {
            android.util.Log.e("PerDiemRepository", "Error getting per diem entries with details", e)
            emptyList()
        }
    }

    suspend fun getPerDiemBillItemized(houseId: String, month: String): Map<String, Any>? {
        return try {
            val params = GetPerDiemBillByMonthParams(
                houseId = houseId,
                month = month
            )
            supabase.postgrest.rpc(
                function = "get_per_diem_bill_itemized",
                parameters = params
            ).decodeSingle<Map<String, Any>>()
        } catch (e: Exception) {
            null
        }
    }

    suspend fun getPerDiemBillByMember(houseId: String, month: String): Map<String, Any>? {
        return try {
            val params = GetPerDiemBillByMonthParams(
                houseId = houseId,
                month = month
            )
            supabase.postgrest.rpc(
                function = "get_per_diem_bill_by_member",
                parameters = params
            ).decodeSingle<Map<String, Any>>()
        } catch (e: Exception) {
            null
        }
    }
}

