GRANT EXECUTE ON FUNCTION public.is_house_admin(UUID, UUID) TO anon;

-- Step 7: Create NEW policies
CREATE POLICY "Members can view house members"
ON house_members
FOR SELECT
TO authenticated
USING (
  user_id = auth.uid()
  OR
  EXISTS (
    SELECT 1
    FROM houses h
    WHERE h.id = house_members.house_id
      AND h.owner_id = auth.uid()
  )
  OR
  public.is_house_member(house_members.house_id, auth.uid())
);

CREATE POLICY "Members can insert themselves"
ON house_members
FOR INSERT
TO authenticated
WITH CHECK (
  user_id = auth.uid()
);

CREATE POLICY "Admins can update members"
ON house_members
FOR UPDATE
TO authenticated
USING (
  role <> 'Owner'
  AND public.is_house_admin(house_members.house_id, auth.uid())
)
WITH CHECK (
  role <> 'Owner'
  AND public.is_house_admin(house_members.house_id, auth.uid())
);

CREATE POLICY "Admins can delete members"
ON house_members
FOR DELETE
TO authenticated
USING (
  role <> 'Owner'
  AND public.is_house_admin(house_members.house_id, auth.uid())
);

