-- Step 1: Create a SECURITY DEFINER function that returns house IDs for a user
CREATE OR REPLACE FUNCTION public.get_user_house_ids(p_user_id UUID)
RETURNS TABLE(house_id UUID)
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
