    ON house_members FOR SELECT
    USING (
        user_id = auth.uid()
        OR
        EXISTS (
            SELECT 1
            FROM house_members AS my_membership
            WHERE my_membership.user_id = auth.uid()
              AND my_membership.house_id = house_members.house_id
        )
    );

