    ON house_members FOR INSERT
    WITH CHECK (user_id = auth.uid());

CREATE POLICY "Admins can update members"
    ON house_members FOR UPDATE
    USING (
        role != 'Owner'
        AND
        EXISTS (
            SELECT 1 FROM house_members AS my_membership
            WHERE my_membership.user_id = auth.uid()
              AND my_membership.house_id = house_members.house_id
              AND my_membership.role IN ('Owner', 'Admin')
        )
    );

CREATE POLICY "Admins can delete members"
    ON house_members FOR DELETE
    USING (
        role != 'Owner'
        AND
        EXISTS (
            SELECT 1 FROM house_members AS my_membership
            WHERE my_membership.user_id = auth.uid()
              AND my_membership.house_id = house_members.house_id
              AND my_membership.role IN ('Owner', 'Admin')
        )
    );

