-- ============================================================================ -- ALTERNATIVE FIX: Simpler approach without helper functions -- ============================================================================ -- This approach simplifies the policies to avoid recursion by only checking -- direct relationships without subqueries on the same table. -- ============================================================================
-- Step 1: Drop existing problematic policies DROP POLICY IF EXISTS "Members can view house members" ON house_members; DROP POLICY IF EXISTS "Admins can update members" ON house_members; DROP POLICY IF EXISTS "Admins can delete members" ON house_members; DROP POLICY IF EXISTS "Members can insert themselves" ON house_members;
-- ============================================================================ -- Step 2: Create simplified policies -- ============================================================================
-- SELECT Policy: Simple approach - users can see members of houses they own -- or their own membership records CREATE POLICY "Members can view house members" ON house_members FOR SELECT USING ( -- User can see their own membership user_id = auth.uid() OR -- User is the house owner EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) );
-- INSERT Policy: Allow users to insert themselves as members CREATE POLICY "Members can insert themselves" ON house_members FOR INSERT WITH CHECK ( user_id = auth.uid() );
-- UPDATE Policy: Only house owners can update members (simplified) CREATE POLICY "Owners can update members" ON house_members FOR UPDATE USING ( -- Cannot change owner role role <> 'Owner' AND -- Only the house owner can update EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) ) WITH CHECK ( -- Cannot change someone to owner role role <> 'Owner' AND -- Only the house owner can update EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) );
-- DELETE Policy: Only house owners can delete members (simplified) CREATE POLICY "Owners can delete members" ON house_members FOR DELETE USING ( -- Cannot delete owner role <> 'Owner' AND -- Only the house owner can delete EXISTS ( SELECT 1 FROM houses h WHERE h.id = house_members.house_id AND h.owner_id = auth.uid() ) );
-- ============================================================================ -- Step 3: If you need admins to also manage members, use this approach instead -- ============================================================================ -- This uses a self-join pattern that PostgreSQL can optimize without recursion
-- Drop the simplified policies first -- DROP POLICY IF EXISTS "Members can view house members" ON house_members; -- DROP POLICY IF EXISTS "Owners can update members" ON house_members; -- DROP POLICY IF EXISTS "Owners can delete members" ON house_members;
-- SELECT with admin support (using self-join) -- CREATE POLICY "Members can view house members" -- ON house_members AS restrictive -- FOR SELECT -- USING ( -- user_id = auth.uid() -- OR -- house_id IN ( -- SELECT DISTINCT house_id -- FROM house_members -- WHERE user_id = auth.uid() -- ) -- );
-- Note: The above might still cause recursion in some PostgreSQL versions. -- The safest approach is to use SECURITY DEFINER functions (first script) -- or keep policies simple (only owners can manage, shown above).
