-- Safer version: only returns necessary info for joining
CREATE OR REPLACE FUNCTION get_house_by_invite_code(code TEXT)
RETURNS TABLE(
    id UUID,
    name TEXT,
    header_image_url TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    -- Validate that invite code exists and return minimal info
    RETURN QUERY
    SELECT
        h.id,
        h.name,
        h.header_image_url
    FROM houses h
    WHERE h.invite_code = UPPER(TRIM(code))
    LIMIT 1;
END;
$$;

GRANT EXECUTE ON FUNCTION get_house_by_invite_code(TEXT) TO authenticated;

-- Separate function to actually join the house
CREATE OR REPLACE FUNCTION join_house_with_invite_code(code TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_house_id UUID;
    v_user_id UUID;
BEGIN
    -- Get current user
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
    END IF;

    -- Find house by invite code
    SELECT id INTO v_house_id
    FROM houses
    WHERE invite_code = UPPER(TRIM(code));

    IF v_house_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid invite code');
    END IF;

    -- Check if already a member
    IF EXISTS (
        SELECT 1 FROM house_members
        WHERE house_id = v_house_id AND user_id = v_user_id
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Already a member');
    END IF;

    -- Insert house member
    INSERT INTO house_members (house_id, user_id, role, joined_at)
    VALUES (v_house_id, v_user_id, 'Member', NOW());

    RETURN jsonb_build_object('success', true, 'house_id', v_house_id);
END;
$$;

GRANT EXECUTE ON FUNCTION join_house_with_invite_code(TEXT) TO authenticated;

COMMENT ON FUNCTION get_house_by_invite_code(TEXT) IS 'Returns minimal house info for invite validation';
COMMENT ON FUNCTION join_house_with_invite_code(TEXT) IS 'Joins user to house using invite code';
